INSERT INTO entropy_chapter_entries VALUES ('radical', 17, 'chapter 四百四十四', 1152, 1155, 4, 4, 11, 4, 'POST-RADICAL Wave 15 entry — PER-STAGE EVENT PAYLOAD。 BASNativeStagePerStepEventPayload typed Codable + 8 fields + factory bridging from chapter 439 per-turn record + 7th BASEventPayloadKind case + EXTENDED BASEventLogReplayBundle to 7 fields。 Sibling of chapter 439 per-turn dispatch event for fine-grained causal-graph extraction。 Engine does NOT auto-emit per-step events;hosts opt-in directly。 ADR-016 → M1155 advance');
